  gCallout.rect(w, h).move(x0, y0).radius(8).fill('#eafaf8').stroke({ color: TEAL, width: 1.3 });
  plainTxt(gCallout, 'Junction b — three branches', x0 + 10, y0 + 16, { size: 10.5, anchor: 'start', fill: '#0c7d77', family: SANS });
  plainTxt(gCallout, 'in:  I₁        out:  I₂ , I₃', x0 + 10, y0 + 36, { size: 12, anchor: 'start', fill: '#1b1b1b' });
  plainTxt(gCallout, 'I₁ = I₂ + I₃', x0 + 10, y0 + 58, { size: 15, anchor: 'start', fill: '#0c7d77', weight: '700' });
  plainTxt(gCallout, '(with I₂ drawn upward the same', x0 + 10, y0 + 76, { size: 9, anchor: 'start', fill: '#666', family: SANS });
  plainTxt(gCallout, 'statement reads I₁ + I₂ = I₃)', x0 + 10, y0 + 87, { size: 9, anchor: 'start', fill: '#666', family: SANS });
}

function render() {
  gGlow.clear(); gCallout.clear(); gAccum.clear();
  gNodes.attr('display', state.lettered ? null : 'none');
  caption.node.textContent = state.lettered ? '(b)' : '(a)';

  var showCur = state.showCurrents || state.junction || state.loop !== 'idle';
  gCur.attr('display', (showCur && state.lettered) ? null : 'none');

  if (state.loop !== 'idle') {
    loopPath(state.loop === 'sum');
    if (state.loop === 'battery') glowBox(192 - 36, BY - 24, 72, 48);
    if (state.loop === 'r1') glowBox(192 - 38, TY - 19, 76, 38);
    if (state.loop === 'r2') glowBox(MX - 19, 185 - 38, 38, 76);
    if (state.loop === 'close') glowBox(LX - 10, TY + 12, 20, BY - TY - 24);
  }
  drawCallout();
  drawAccum();
}

/* ---------- controls ---------- */
function syncInputs() {
  document.getElementById('labelViewInput').checked = state.lettered;
  document.getElementById('loopTraceInput').value = state.loop;
  document.getElementById('showCurrentsInput').checked =
    state.showCurrents || state.junction || state.loop !== 'idle';
}

function toggle_labelView(on) {
  state.lettered = on;
  if (!on) { state.junction = false; state.loop = 'idle'; }
  syncInputs(); render();
}

function set_loopTrace(v) {
  state.loop = v;
  if (v !== 'idle') { state.lettered = true; state.junction = false; }
  syncInputs(); render();
}

function toggle_showCurrents(on) {
  state.showCurrents = on;
  if (on) state.lettered = true;
  syncInputs(); render();
}

function trigger_junctionPick() {
  state.junction = !state.junction;
  if (state.junction) { state.lettered = true; state.loop = 'idle'; }
  syncInputs(); render();
}

function trigger_reset() { goStep(0); }

/* ---------- demo player ---------- */
var steps = [
  { title: 'The bare circuit',
    narration: 'Two loops share a middle branch: R1 and R3 sit on top, R2 divides the loops, R4 is on the right, and two opposing batteries drive the bottom. Nothing here tells you where to start an analysis.',
    state: { lettered: false, loop: 'idle', junction: false } },
  { title: 'Add the labels',
    narration: 'Flip to panel (b): six teal dots and the letters a–f appear over the identical circuit. The physics is unchanged; the letters simply give you names for the points you will write equations about.',
    state: { lettered: true, loop: 'idle', junction: false } },
  { title: 'Find the junctions',
    narration: 'Only b and e have three wires meeting. Click either one to see its three branch currents; the junction rule says what flows in must flow out, so I1 + I2 = I3.',
    state: { lettered: true, loop: 'idle', junction: true } },
  { title: 'Start a loop',
    narration: 'Pick the left loop abef and choose a traversal direction. The accumulator panel opens empty, ready to collect signed potential changes.',
    state: { lettered: true, loop: 'choose', junction: false } },
  { title: 'Cross the battery',
    narration: 'Moving through V1 from − to + is a potential rise of +24.00 V. The term is added to the running sum and the battery glows.',
    state: { lettered: true, loop: 'battery', junction: false } },
  { title: 'Drop across R1',
    narration: 'Traversing R1 in the direction of I1 gives a drop of −I1(3.00 Ω). Sign comes entirely from the direction of travel relative to the assumed current.',
    state: { lettered: true, loop: 'r1', junction: false } },
  { title: 'Drop across R2',
    narration: 'Continuing down the shared middle branch through R2 adds −I2(3.00 Ω). The shared branch is what couples the two loops together.',
    state: { lettered: true, loop: 'r2', junction: false } },
  { title: 'Close the loop',
    narration: 'Returning along the plain left wire adds nothing. Back at the starting node, the potential must be what it was when you left.',
    state: { lettered: true, loop: 'close', junction: false } },
  { title: 'The loop equation',
    narration: 'All terms sum to zero: 24.00 − 3.00 I1 − 3.00 I2 = 0. Repeat for the right loop and combine with the junction equation to solve for all three currents.',
    state: { lettered: true, loop: 'sum', junction: false } }
];
var stepIdx = 0;

function goStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  state.lettered = s.state.lettered;
  state.loop = s.state.loop;
  state.junction = s.state.junction;
  document.getElementById('demoTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'step ' + (stepIdx + 1) + ' / ' + steps.length;
  syncInputs(); render();
}
function nextStep() { goStep(stepIdx + 1); }
function prevStep() { goStep(stepIdx - 1); }

goStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Kirchhoff's junction and loop rules turn a two-loop circuit into a solvable set of equations: currents must balance at every junction, and signed potential changes must sum to zero around every closed path.
KEY INSIGHT (what students should walk away understanding): Labeling nodes is not decoration — it converts a picture of wires into a bookkeeping system where each junction gives a current equation and each closed loop gives a signed voltage equation, and together they pin down every unknown current.
DEMO STEPS: 9 guided steps — implement the step player in #ui

