// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 600, 470);

var LX = 85, MX = 300, RX = 515, TY = 85, BY = 315;
var BLUE = '#1f5ca8', TEAL = '#12b0a8', AMBER = '#eda022', RED = '#cf332c';
var SERIF = "Georgia,'Times New Roman',Times,serif";
var SANS = "system-ui,'Helvetica Neue',Arial,sans-serif";
var B1X = 192, B2X = 407, BHALF = 16;

var gGlow = draw.group(), gWire = draw.group(), gComp = draw.group(),
    gLabel = draw.group(), gNodes = draw.group(), gCur = draw.group(),
    gCallout = draw.group(), gAccum = draw.group(), gHit = draw.group();

var state = { lettered: false, loop: 'idle', junction: false, showCurrents: false };

/* ---------- small drawing helpers ---------- */
function plainTxt(g, s, x, y, o) {
  o = o || {};
  var t = g.plain(s).font({
    family: o.family || SERIF,
    size: o.size || 14,
    style: o.italic ? 'italic' : 'normal',
    weight: o.weight || 'normal'
  });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y, 'text-anchor': o.anchor || 'middle', 'dominant-baseline': 'middle' });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}

function textLen(t, s, size) {
  try { return t.node.getComputedTextLength(); } catch (e) { return s.length * size * 0.52; }
}

/* italic symbol + upright remainder, e.g.  R₁  = 3.00 Ω */
function mathLabel(g, x, y, sym, rest, align, size) {
  size = size || 15;
  var a = plainTxt(g, sym, 0, y, { size: size, italic: true, anchor: 'end', halo: 3 });
  var b = plainTxt(g, rest, 0, y, { size: size, anchor: 'start', halo: 3 });
  var wa = textLen(a, sym, size), wb = textLen(b, rest, size), gap = 4, x0;
  if (align === 'end') x0 = x - wb - gap;
  else if (align === 'start') x0 = x + wa;
  else x0 = x - (wa + gap + wb) / 2 + wa;
  a.attr({ x: x0 });
  b.attr({ x: x0 + gap });
  return [a, b];
}

function wire(x1, y1, x2, y2) {
  return gWire.line(x1, y1, x2, y2).stroke({ color: '#000', width: 2, linecap: 'round' });
}

function resistor(g, cx, cy, orient) {
  var len = 62, amp = 11.5, half = len / 2, n = 6, pts = [], i;
  if (orient === 'h') {
    pts.push([cx - half, cy]);
    for (i = 0; i < n; i++) pts.push([cx - half + len * (i + 0.5) / n, cy + (i % 2 ? amp : -amp)]);
    pts.push([cx + half, cy]);
  } else {
    pts.push([cx, cy - half]);
    for (i = 0; i < n; i++) pts.push([cx + (i % 2 ? amp : -amp), cy - half + len * (i + 0.5) / n]);
    pts.push([cx, cy + half]);
  }
  return g.polyline(pts).fill('none').stroke({ color: BLUE, width: 3.2, linejoin: 'round', linecap: 'round' });
}

/* multi-cell battery: alternating LONG-thin (+ side) and SHORT-thick (− side) plates */
function battery(g, cx, cy, plusLeft) {
  var offs = [-BHALF, -5.5, 5.5, BHALF], i, isLong, h, w;
  for (i = 0; i < 4; i++) {
    isLong = plusLeft ? (i % 2 === 0) : (i % 2 === 1);
    h = isLong ? 36 : 18;
    w = isLong ? 2.1 : 4.6;
    g.line(cx + offs[i], cy - h / 2, cx + offs[i], cy + h / 2)
      .stroke({ color: '#000', width: w, linecap: 'butt' });
  }
  plainTxt(g, plusLeft ? '+' : '−', cx - 29, cy - 1, { size: 18, halo: 4 });
  plainTxt(g, plusLeft ? '−' : '+', cx + 29, cy - 1, { size: 18, halo: 4 });
}

function headPoly(g, x, y, ux, uy, s, color) {
  var px = -uy, py = ux;
  return g.polygon([
    [x + ux * s, y + uy * s],
    [x - ux * s * 0.35 + px * s * 0.6, y - uy * s * 0.35 + py * s * 0.6],
    [x - ux * s * 0.35 - px * s * 0.6, y - uy * s * 0.35 - py * s * 0.6]
  ]).fill(color);
}

function curArrow(g, x1, y1, x2, y2, color) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy), ux = dx / L, uy = dy / L;
  g.line(x1, y1, x2 - ux * 6, y2 - uy * 6).stroke({ color: color, width: 2.6, linecap: 'round' });
  headPoly(g, x2 - ux * 5, y2 - uy * 5, ux, uy, 8, color);
}

function hit(x, y, w, h, tip, title, body, cb) {
  var r = gHit.rect(w, h).move(x, y).fill('#fff').attr({ 'fill-opacity': 0, 'pointer-events': 'all' });
  r.css('cursor', 'pointer');
  r.on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { if (cb) cb(); else showPopup(title, body); });
  return r;
}

/* ---------- static circuit ---------- */
wire(LX, TY, 161, TY); wire(223, TY, MX, TY); wire(MX, TY, 376, TY); wire(438, TY, RX, TY);
wire(LX, TY, LX, BY);
wire(MX, TY, MX, 154); wire(MX, 216, MX, BY);
wire(RX, TY, RX, 154); wire(RX, 216, RX, BY);
wire(LX, BY, B1X - BHALF, BY);
wire(B1X + BHALF, BY, B2X - BHALF, BY);
wire(B2X + BHALF, BY, RX, BY);

resistor(gComp, B1X, TY, 'h');
resistor(gComp, B2X, TY, 'h');
resistor(gComp, MX, 185, 'v');
resistor(gComp, RX, 185, 'v');
battery(gComp, B1X, BY, true);
battery(gComp, B2X, BY, false);

mathLabel(gLabel, B1X, TY - 34, 'R₁', '= 3.00 Ω', 'center', 15);
mathLabel(gLabel, B2X, TY - 34, 'R₃', '= 3.00 Ω', 'center', 15);
mathLabel(gLabel, MX - 24, 185, 'R₂', '= 3.00 Ω', 'end', 15);
mathLabel(gLabel, RX - 24, 185, 'R₄', '= 4.00 Ω', 'end', 15);
mathLabel(gLabel, B1X, BY - 40, 'V₁', '= 24.00 V', 'center', 15);
mathLabel(gLabel, B2X, BY - 40, 'V₂', '= 29.00 V', 'center', 15);

var caption = plainTxt(gLabel, '(a)', 300, 362, { size: 15 });

/* ---------- lettered nodes ---------- */
var NODES = [
  { id: 'a', x: LX, y: TY, lx: LX - 18, ly: TY - 15 },
  { id: 'b', x: MX, y: TY, lx: MX, ly: TY - 20 },
  { id: 'c', x: RX, y: TY, lx: RX + 18, ly: TY - 15 },
  { id: 'f', x: LX, y: BY, lx: LX - 18, ly: BY + 17 },
  { id: 'e', x: MX, y: BY, lx: MX, ly: BY + 22 },
  { id: 'd', x: RX, y: BY, lx: RX + 18, ly: BY + 17 }
];
NODES.forEach(function (n) {
  gNodes.circle(11).center(n.x, n.y).fill(TEAL);
  plainTxt(gNodes, n.id, n.lx, n.ly, { size: 16, italic: true, halo: 3 });
});
gNodes.attr('display', 'none');

/* ---------- current arrows (I₁ into b, I₂ down out of b, I₃ right out of b) ---------- */
curArrow(gCur, 105, TY, 150, TY, RED);
plainTxt(gCur, 'I₁', 127, TY - 15, { size: 14, italic: true, fill: RED, halo: 3 });
curArrow(gCur, 320, TY, 366, TY, RED);
plainTxt(gCur, 'I₃', 343, TY - 15, { size: 14, italic: true, fill: RED, halo: 3 });
curArrow(gCur, MX, 102, MX, 146, RED);
plainTxt(gCur, 'I₂', MX + 18, 124, { size: 14, italic: true, fill: RED, halo: 3 });
gCur.attr('display', 'none');

/* ---------- hover / click hit areas ---------- */
hit(B1X - 34, TY - 20, 68, 40, 'R₁ = 3.00 Ω — branch a–b, carries I₁', 'Resistor R₁',
  'R₁ = 3.00 Ω sits in the top-left branch between nodes a and b. Walking a loop through it in the direction of I₁ gives a potential drop of −I₁R₁; walking against I₁ gives a rise.');
hit(B2X - 34, TY - 20, 68, 40, 'R₃ = 3.00 Ω — branch b–c, carries I₃', 'Resistor R₃',
  'R₃ = 3.00 Ω is in the top-right branch between b and c. It belongs only to the right loop, so it appears in the right-loop equation together with R₄ and V₂.');
hit(MX - 20, 152, 40, 66, 'R₂ = 3.00 Ω — shared middle branch b–e, carries I₂', 'Resistor R₂ (shared branch)',
  'R₂ = 3.00 Ω lies on the branch that both loops share. Because its current I₂ appears in both loop equations, it is what couples the two loops into a single system of equations.');
