<label style="flex-direction:row;align-items:center;gap:6px"><input id="showCurrentsInput" type="checkbox" onchange="toggle_showCurrents(this.checked)"> show current arrows I₁ I₂ I₃</label>
<button onclick="trigger_junctionPick()">Junction rule at b / e</button>
<button onclick="trigger_reset()">Reset to step 1</button>
<span style="font-size:10.5px;color:#666;line-height:1.4">Hover any element for its value. Click a teal node, a resistor, or a battery for detail.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 600, 470);

var LX = 85, MX = 300, RX = 515, TY = 85, BY = 315;
var BLUE = '#1f5ca8', TEAL = '#12b0a8', AMBER = '#eda022', RED = '#cf332c';
var SERIF = "Georgia,'Times New Roman',Times,serif";
var SANS = "system-ui,'Helvetica Neue',Arial,sans-serif";
var B1X = 192, B2X = 407, BHALF = 16;

var gGlow = draw.group(), gWire = draw.group(), gComp = draw.group(),
    gLabel = draw.group(), gNodes = draw.group(), gCur = draw.group(),
    gCallout = draw.group(), gAccum = draw.group(), gHit = draw.group();

var state = { lettered: false, loop: 'idle', junction: false, showCurrents: false };

/* ---------- small drawing helpers ---------- */
function plainTxt(g, s, x, y, o) {
  o = o || {};
  var t = g.plain(s).font({
    family: o.family || SERIF,
    size: o.size || 14,
    style: o.italic ? 'italic' : 'normal',
    weight: o.weight || 'normal'
  });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y, 'text-anchor': o.anchor || 'middle', 'dominant-baseline': 'middle' });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}

function textLen(t, s, size) {
  try { return t.node.getComputedTextLength(); } catch (e) { return s.length * size * 0.52; }
}

/* italic symbol + upright remainder, e.g.  R₁  = 3.00 Ω */
function mathLabel(g, x, y, sym, rest, align, size) {
  size = size || 15;
  var a = plainTxt(g, sym, 0, y, { size: size, italic: true, anchor: 'end', halo: 3 });
  var b = plainTxt(g, rest, 0, y, { size: size, anchor: 'start', halo: 3 });
  var wa = textLen(a, sym, size), wb = textLen(b, rest, size), gap = 4, x0;
  if (align === 'end') x0 = x - wb - gap;
  else if (align === 'start') x0 = x + wa;
  else x0 = x - (wa + gap + wb) / 2 + wa;
  a.attr({ x: x0 });
  b.attr({ x: x0 + gap });
  return [a, b];
}

function wire(x1, y1, x2, y2) {
  return gWire.line(x1, y1, x2, y2).stroke({ color: '#000', width: 2, linecap: 'round' });
}

function resistor(g, cx, cy, orient) {
  var len = 62, amp = 11.5, half = len / 2, n = 6, pts = [], i;
  if (orient === 'h') {
    pts.push([cx - half, cy]);
    for (i = 0; i < n; i++) pts.push([cx - half + len * (i + 0.5) / n, cy + (i % 2 ? amp : -amp)]);
    pts.push([cx + half, cy]);
  } else {
    pts.push([cx, cy - half]);
    for (i = 0; i < n; i++) pts.push([cx + (i % 2 ? amp : -amp), cy - half + len * (i + 0.5) / n]);
    pts.push([cx, cy + half]);
  }
  return g.polyline(pts).fill('none').stroke({ color: BLUE, width: 3.2, linejoin: 'round', linecap: 'round' });
}

/* multi-cell battery: alternating LONG-thin (+ side) and SHORT-thick (− side) plates */
function battery(g, cx, cy, plusLeft) {
  var offs = [-BHALF, -5.5, 5.5, BHALF], i, isLong, h, w;
  for (i = 0; i < 4; i++) {
    isLong = plusLeft ? (i % 2 === 0) : (i % 2 === 1);
    h = isLong ? 36 : 18;
    w = isLong ? 2.1 : 4.6;
    g.line(cx + offs[i], cy - h / 2, cx + offs[i], cy + h / 2)
      .stroke({ color: '#000', width: w, linecap: 'butt' });
  }
  plainTxt(g, plusLeft ? '+' : '−', cx - 29, cy - 1, { size: 18, halo: 4 });
  plainTxt(g, plusLeft ? '−' : '+', cx + 29, cy - 1, { size: 18, halo: 4 });
}

function headPoly(g, x, y, ux, uy, s, color) {
  var px = -uy, py = ux;
  return g.polygon([
    [x + ux * s, y + uy * s],
    [x - ux * s * 0.35 + px * s * 0.6, y - uy * s * 0.35 + py * s * 0.6],
    [x - ux * s * 0.35 - px * s * 0.6, y - uy * s * 0.35 - py * s * 0.6]
  ]).fill(color);
}

function curArrow(g, x1, y1, x2, y2, color) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy), ux = dx / L, uy = dy / L;
  g.line(x1, y1, x2 - ux * 6, y2 - uy * 6).stroke({ color: color, width: 2.6, linecap: 'round' });
  headPoly(g, x2 - ux * 5, y2 - uy * 5, ux, uy, 8, color);
}

function hit(x, y, w, h, tip, title, body, cb) {
  var r = gHit.rect(w, h).move(x, y).fill('#fff').attr({ 'fill-opacity': 0, 'pointer-events': 'all' });
  r.css('cursor', 'pointer');
  r.on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { if (cb) cb(); else showPopup(title, body); });
  return r;
}

/* ---------- static circuit ---------- */
wire(LX, TY, 161, TY); wire(223, TY, MX, TY); wire(MX, TY, 376, TY); wire(438, TY, RX, TY);
wire(LX, TY, LX, BY);
wire(MX, TY, MX, 154); wire(MX, 216, MX, BY);
wire(RX, TY, RX, 154); wire(RX, 216, RX, BY);
wire(LX, BY, B1X - BHALF, BY);
wire(B1X + BHALF, BY, B2X - BHALF, BY);
wire(B2X + BHALF, BY, RX, BY);

resistor(gComp, B1X, TY, 'h');
resistor(gComp, B2X, TY, 'h');
resistor(gComp, MX, 185, 'v');
resistor(gComp, RX, 185, 'v');
battery(gComp, B1X, BY, true);
battery(gComp, B2X, BY, false);

mathLabel(gLabel, B1X, TY - 34, 'R₁', '= 3.00 Ω', 'center', 15);
mathLabel(gLabel, B2X, TY - 34, 'R₃', '= 3.00 Ω', 'center', 15);
mathLabel(gLabel, MX - 24, 185, 'R₂', '= 3.00 Ω', 'end', 15);
mathLabel(gLabel, RX - 24, 185, 'R₄', '= 4.00 Ω', 'end', 15);
mathLabel(gLabel, B1X, BY - 40, 'V₁', '= 24.00 V', 'center', 15);
mathLabel(gLabel, B2X, BY - 40, 'V₂', '= 29.00 V', 'center', 15);

var caption = plainTxt(gLabel, '(a)', 300, 362, { size: 15 });

/* ---------- lettered nodes ---------- */
var NODES = [
  { id: 'a', x: LX, y: TY, lx: LX - 18, ly: TY - 15 },
  { id: 'b', x: MX, y: TY, lx: MX, ly: TY - 20 },
  { id: 'c', x: RX, y: TY, lx: RX + 18, ly: TY - 15 },
  { id: 'f', x: LX, y: BY, lx: LX - 18, ly: BY + 17 },
  { id: 'e', x: MX, y: BY, lx: MX, ly: BY + 22 },
  { id: 'd', x: RX, y: BY, lx: RX + 18, ly: BY + 17 }
];
NODES.forEach(function (n) {
  gNodes.circle(11).center(n.x, n.y).fill(TEAL);
  plainTxt(gNodes, n.id, n.lx, n.ly, { size: 16, italic: true, halo: 3 });
});
gNodes.attr('display', 'none');

/* ---------- current arrows (I₁ into b, I₂ down out of b, I₃ right out of b) ---------- */
curArrow(gCur, 105, TY, 150, TY, RED);
plainTxt(gCur, 'I₁', 127, TY - 15, { size: 14, italic: true, fill: RED, halo: 3 });
curArrow(gCur, 320, TY, 366, TY, RED);
plainTxt(gCur, 'I₃', 343, TY - 15, { size: 14, italic: true, fill: RED, halo: 3 });
curArrow(gCur, MX, 102, MX, 146, RED);
plainTxt(gCur, 'I₂', MX + 18, 124, { size: 14, italic: true, fill: RED, halo: 3 });
gCur.attr('display', 'none');

/* ---------- hover / click hit areas ---------- */
hit(B1X - 34, TY - 20, 68, 40, 'R₁ = 3.00 Ω — branch a–b, carries I₁', 'Resistor R₁',
  'R₁ = 3.00 Ω sits in the top-left branch between nodes a and b. Walking a loop through it in the direction of I₁ gives a potential drop of −I₁R₁; walking against I₁ gives a rise.');
hit(B2X - 34, TY - 20, 68, 40, 'R₃ = 3.00 Ω — branch b–c, carries I₃', 'Resistor R₃',
  'R₃ = 3.00 Ω is in the top-right branch between b and c. It belongs only to the right loop, so it appears in the right-loop equation together with R₄ and V₂.');
hit(MX - 20, 152, 40, 66, 'R₂ = 3.00 Ω — shared middle branch b–e, carries I₂', 'Resistor R₂ (shared branch)',
  'R₂ = 3.00 Ω lies on the branch that both loops share. Because its current I₂ appears in both loop equations, it is what couples the two loops into a single system of equations.');
hit(RX - 20, 152, 40, 66, 'R₄ = 4.00 Ω — branch c–d, carries I₃', 'Resistor R₄',
  'R₄ = 4.00 Ω is on the right vertical wire. Together with R₃ it is in series with the right-hand emf V₂ along the outer right branch.');
hit(B1X - 40, BY - 26, 80, 52, 'V₁ = 24.00 V — + terminal toward f, − toward e', 'Battery V₁',
  'V₁ = 24.00 V drives the left loop with its + plate (the long thin plate) on the left. Entering at the − terminal and leaving at the + terminal is a rise of +24.00 V; traversing the other way is a drop of −24.00 V.');
hit(B2X - 40, BY - 26, 80, 52, 'V₂ = 29.00 V — − terminal toward e, + toward d', 'Battery V₂',
  'V₂ = 29.00 V opposes V₁: its + plate faces the right-hand side. Its sign in the right-loop equation is fixed by the direction in which you walk the loop, not by where it sits on the page.');
hit(LX - 11, TY + 12, 22, BY - TY - 24, 'Plain wire f–a — no resistance, no emf', 'Bare connecting wire',
  'This segment contains no component, so it contributes zero to the loop sum. Ideal wires have no potential change along them — which is why all six labelled points reduce to just a handful of distinct potentials.');

NODES.forEach(function (n) {
  var isJ = (n.id === 'b' || n.id === 'e');
  var c = gHit.circle(26).center(n.x, n.y).fill('#fff').attr({ 'fill-opacity': 0, 'pointer-events': 'all' });
  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) {
    showTooltip('Node ' + n.id + (isJ ? ' — junction of three branches: I₁ = I₂ + I₃ (click)' : ' — corner, only two wires meet'), e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    if (isJ) {
      state.lettered = true; state.loop = 'idle'; state.junction = true;
      syncInputs(); render();
      showPopup('Junction rule at ' + n.id,
        'Three branches meet here, so the charge arriving each second must leave each second. With the arrows as drawn — I₁ flowing in along the top-left branch, I₂ flowing down the middle branch and I₃ flowing on toward c — the rule reads I₁ = I₂ + I₃. Nodes b and e give exactly the same equation, so this two-loop circuit supplies only one independent junction equation.');
    } else {
      state.lettered = true; syncInputs(); render();
      showPopup('Node ' + n.id + ' is not a junction',
        'Only two wires meet at ' + n.id + ', so the current entering simply equals the current leaving — no new information. Junction equations come only from points where three or more branches meet.');
    }
  });
});

/* ---------- dynamic layers ---------- */
function glowBox(x, y, w, h) {
  return gGlow.rect(w, h).move(x, y).radius(7)
    .fill({ color: AMBER, opacity: 0.25 }).stroke({ color: AMBER, width: 2 });
}

function loopPath(strong) {
  var pts = [[293, 308], [92, 308], [92, 92], [293, 92], [293, 308]];
  var p = gGlow.polyline(pts).fill('none')
    .stroke({ color: AMBER, width: strong ? 5 : 3.2, linecap: 'round', linejoin: 'round' })
    .opacity(strong ? 0.6 : 0.8);
  if (!strong) p.attr('stroke-dasharray', '8,6');
  [[130, 308, -1, 0], [92, 240, 0, -1], [250, 92, 1, 0], [293, 255, 0, 1]].forEach(function (a) {
    headPoly(gGlow, a[0], a[1], a[2], a[3], 8, AMBER).opacity(0.95);
  });
}

var DESC = {
  choose: 'Direction: e → f → a → b → e.  Signed changes must total zero.',
  battery: 'e → f through V₁ : enter −, leave + ⇒ rise of + 24.00 V',
  r1: 'a → b through R₁ , moving with I₁ ⇒ drop − (3.00 Ω) I₁',
  r2: 'b → e through R₂ , moving with I₂ ⇒ drop − (3.00 Ω) I₂',
  close: 'f → a is bare wire — no emf, no resistance ⇒ adds 0',
  sum: 'Back at e the potential is unchanged, so every term must cancel.'
};
var ORDER = ['choose', 'battery', 'r1', 'r2', 'close', 'sum'];

function drawAccum() {
  if (state.loop === 'idle') return;
  var idx = ORDER.indexOf(state.loop);
  var x0 = 52, y0 = 376, w = 496, h = 90;
  gAccum.rect(w, h).move(x0, y0).radius(8).fill('#fdf7ea').stroke({ color: '#e2c68d', width: 1 });
  plainTxt(gAccum, 'Loop rule — left loop  e → f → a → b → e', x0 + 14, y0 + 17,
    { size: 12.5, anchor: 'start', fill: '#8a6412', family: SANS });
  plainTxt(gAccum, DESC[state.loop], x0 + 14, y0 + 39, { size: 11, anchor: 'start', fill: '#3a3a3a', family: SANS });

  var terms = [];
  if (idx >= 1) terms.push('+ 24.00 V');
  if (idx >= 2) terms.push('− (3.00 Ω) I₁');
  if (idx >= 3) terms.push('− (3.00 Ω) I₂');
  if (idx >= 4) terms.push('+ 0');

  if (state.loop === 'sum') {
    plainTxt(gAccum, '24.00 − 3.00 I₁ − 3.00 I₂ = 0', x0 + 14, y0 + 63,
      { size: 17, anchor: 'start', fill: '#a4550c', weight: '700' });
    plainTxt(gAccum, 'junction:  I₁ = I₂ + I₃   ·   repeat for the right loop, then solve for I₁ , I₂ , I₃',
      x0 + 14, y0 + 81, { size: 10, anchor: 'start', fill: '#6d6d6d', family: SANS });
  } else {
    plainTxt(gAccum, terms.length ? terms.join('     ') : 'running sum:  (empty — nothing crossed yet)',
      x0 + 14, y0 + 66, { size: 15, anchor: 'start', fill: terms.length ? '#1b1b1b' : '#8a8a8a' });
  }
}

function drawCallout() {
  if (!state.junction) return;
  gGlow.circle(28).center(MX, TY).fill({ color: AMBER, opacity: 0.35 });
  gGlow.circle(28).center(MX, BY).fill({ color: AMBER, opacity: 0.22 });
  var x0 = 322, y0 = 218, w = 182, h = 88;
  gCallout.rect(w, h).move(x0, y0).radius(8).fill('#eafaf8').stroke({ color: TEAL, width: 1.3 });
  plainTxt(gCallout, 'Junction b — three branches', x0 + 10, y0 + 16, { size: 10.5, anchor: 'start', fill: '#0c7d77', family: SANS });
  plainTxt(gCallout, 'in:  I₁        out:  I₂ , I₃', x0 + 10, y0 + 36, { size: 12, anchor: 'start', fill: '#1b1b1b' });
  plainTxt(gCallout, 'I₁ = I₂ + I₃', x0 + 10, y0 + 58, { size: 16, anchor: 'start', fill: '#0c7d77', weight: '700' });
  plainTxt(gCallout, 'same equation at node e', x0 + 10, y0 + 76, { size: 9.5, anchor: 'start', fill: '#666', family: SANS });
}

function render() {
  gGlow.clear(); gCallout.clear(); gAccum.clear();
  gNodes.attr('display', state.lettered ? null : 'none');
  caption.node.textContent = state.lettered ? '(b)' : '(a)';

  var showCur = state.showCurrents || state.junction || state.loop !== 'idle';
  gCur.attr('display', (showCur && state.lettered) ? null : 'none');

  if (state.loop !== 'idle') {
    loopPath(state.loop === 'sum');
    if (state.loop === 'battery') glowBox(B1X - 40, BY - 26, 80, 52);
    if (state.loop === 'r1') glowBox(B1X - 38, TY - 20, 76, 40);
    if (state.loop === 'r2') glowBox(MX - 20, 185 - 38, 40, 76);
    if (state.loop === 'close') glowBox(LX - 11, TY + 12, 22, BY - TY - 24);
  }
  drawCallout();
  drawAccum();
}

/* ---------- controls ---------- */
function syncInputs() {
  var a = document.getElementById('panelABtn'), b = document.getElementById('panelBBtn');
  if (a && b) {
    a.className = state.lettered ? '' : 'active';
    b.className = state.lettered ? 'active' : '';
  }
  document.getElementById('loopTraceInput').value = state.loop;
  document.getElementById('showCurrentsInput').checked =
    state.showCurrents || state.junction || state.loop !== 'idle';
}

function setPanel(lettered) {
  state.lettered = lettered;
  if (!lettered) { state.junction = false; state.loop = 'idle'; }
  syncInputs(); render();
}
function toggle_labelView(on) { setPanel(!!on); }

function set_loopTrace(v) {
  state.loop = v;
  if (v !== 'idle') { state.lettered = true; state.junction = false; }
  syncInputs(); render();
}

function toggle_showCurrents(on) {
  state.showCurrents = on;
  if (on) state.lettered = true;
  syncInputs(); render();
}

function trigger_junctionPick() {
  state.junction = !state.junction;
  if (state.junction) { state.lettered = true; state.loop = 'idle'; }
  syncInputs(); render();
}

function trigger_reset() { goStep(0); }

/* ---------- demo player ---------- */
var steps = [
  { title: 'The bare circuit',
    narration: 'Two loops share a middle branch: R1 and R3 sit on top, R2 divides the loops, R4 is on the right, and two opposing batteries drive the bottom. Nothing here tells you where to start an analysis.',
    state: { lettered: false, loop: 'idle', junction: false } },
  { title: 'Add the labels',
    narration: 'Switch to panel (b): six teal dots and the letters a–f appear over the identical circuit. The physics is unchanged; the letters simply give you names for the points you will write equations about.',
    state: { lettered: true, loop: 'idle', junction: false } },
  { title: 'Find the junctions',
    narration: 'Only b and e have three wires meeting. Click either one to see its three branch currents: I1 arrives along the top-left branch while I2 leaves downward and I3 leaves toward c, so what flows in must flow out — I1 = I2 + I3.',
    state: { lettered: true, loop: 'idle', junction: true } },
  { title: 'Start a loop',
    narration: 'Pick the left loop abef and choose a traversal direction. The accumulator panel opens empty, ready to collect signed potential changes.',
    state: { lettered: true, loop: 'choose', junction: false } },
  { title: 'Cross the battery',
    narration: 'Moving through V1 from − to + is a potential rise of +24.00 V. The term is added to the running sum and the battery glows.',
    state: { lettered: true, loop: 'battery', junction: false } },
  { title: 'Drop across R1',
    narration: 'Traversing R1 in the direction of I1 gives a drop of −I1(3.00 Ω). Sign comes entirely from the direction of travel relative to the assumed current.',
    state: { lettered: true, loop: 'r1', junction: false } },
  { title: 'Drop across R2',
    narration: 'Continuing down the shared middle branch through R2 adds −I2(3.00 Ω). The shared branch is what couples the two loops together.',
    state: { lettered: true, loop: 'r2', junction: false } },
  { title: 'Close the loop',
    narration: 'Returning along the plain left wire adds nothing. Back at the starting node, the potential must be what it was when you left.',
    state: { lettered: true, loop: 'close', junction: false } },
  { title: 'The loop equation',
    narration: 'All terms sum to zero: 24.00 − 3.00 I1 − 3.00 I2 = 0. Repeat for the right loop and combine with the junction equation I1 = I2 + I3 to solve for all three currents.',
    state: { lettered: true, loop: 'sum', junction: false } }
];
var stepIdx = 0;

function goStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  state.lettered = s.state.lettered;
  state.loop = s.state.loop;
  state.junction = s.state.junction;
  document.getElementById('demoTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'step ' + (stepIdx + 1) + ' / ' + steps.length;
  syncInputs(); render();
}
function nextStep() { goStep(stepIdx + 1); }
function prevStep() { goStep(stepIdx - 1); }

goStep(0);
window.__markRendered();
// @FIGURE_CODE_END

