  gDetail.attr('display', both ? 'none' : null);
  gHit.attr('display', both ? 'none' : null);
  if (both) { gCur.attr('display', 'none'); return; }

  var lettered = (state.view === 'b');
  detail.nodes.attr('display', lettered ? null : 'none');
  detail.caption.node.textContent = lettered ? '(b)' : '(a)';

  var showCur = state.showCurrents || state.junction || state.loop !== 'idle';
  gCur.attr('display', (showCur && lettered) ? null : 'none');

  if (state.loop !== 'idle') {
    loopPath(state.loop === 'sum');
    if (state.loop === 'battery') glowBox(B1X - 42, BY - 24, 84, 48);
    if (state.loop === 'wire') glowBox(LX - 11, TY + 14, 22, BY - TY - 28);
    if (state.loop === 'r1') glowBox(B1X - 36, TY - 18, 72, 36);
    if (state.loop === 'r2') glowBox(MX - 19, 185 - 34, 38, 68);
  }
